<section class="directory-header shell pos-header"><div><span class="eyebrow">Customer directory / Profile</span><h1><?= esc($customer['full_name']) ?></h1><p>Customer #<?= esc((string) $customer['id']) ?> · Added <?= esc(date('M j, Y', strtotime($customer['created_at']))) ?></p></div><div class="directory-actions"><a class="button secondary" href="<?= site_url('customers') ?>">Back to customers</a><?php if ($customer['is_active']): ?><a class="button primary" href="<?= site_url('customers/' . $customer['id'] . '/edit') ?>">Edit customer</a><?php endif; ?></div></section>
